CREATE TABLE website_analysis_daily_usage (utc_date TEXT PRIMARY KEY CHECK (utc_date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND date(utc_date) = utc_date), websites_admitted INTEGER NOT NULL CHECK (typeof(websites_admitted) = 'integer' AND websites_admitted >= 0 AND websites_admitted <= 50), gemini_requests_used INTEGER NOT NULL CHECK (typeof(gemini_requests_used) = 'integer' AND gemini_requests_used >= 0));
CREATE TABLE website_analysis_daily_admissions (utc_date TEXT NOT NULL CHECK (utc_date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND date(utc_date) = utc_date), evidence_id INTEGER NOT NULL CHECK (typeof(evidence_id) = 'integer' AND evidence_id > 0), PRIMARY KEY (utc_date, evidence_id));
CREATE TRIGGER website_analysis_daily_admissions_cap BEFORE INSERT ON website_analysis_daily_admissions FOR EACH ROW BEGIN INSERT INTO website_analysis_daily_usage (utc_date, websites_admitted, gemini_requests_used) VALUES (NEW.utc_date, 0, 0) ON CONFLICT (utc_date) DO NOTHING; SELECT RAISE(ABORT, 'daily website cap') WHERE (SELECT COUNT(*) FROM website_analysis_daily_admissions WHERE utc_date = NEW.utc_date) >= 50; END;
CREATE TRIGGER website_analysis_daily_admissions_count AFTER INSERT ON website_analysis_daily_admissions FOR EACH ROW BEGIN UPDATE website_analysis_daily_usage SET websites_admitted = websites_admitted + 1 WHERE utc_date = NEW.utc_date; END;
